"use client"

import { forwardRef, useId, useImperativeHandle, type ReactNode } from "react"

import {
  useFileSizeInput,
  type UseFileSizeInputOptions,
} from "./use-filesize-input"

export interface FileSizeInputProps extends UseFileSizeInputOptions {
  /** Visible label. Supply this or `aria-label` — a field with neither has no accessible name. */
  label?: ReactNode
  /** Helper text under the field. Replaced by the error message while one is showing. */
  hint?: ReactNode
  /** Show the raw byte count as a trailing affix. Default true. */
  showBytes?: boolean
}

/**
 * A file size field.
 *
 * Emits bytes. Keeps `MB` (1000²) and `MiB` (1024²) distinct rather than
 * silently converting — they differ by 4.9%, which is the gap between a
 * "100 MB limit" and a user's file being rejected.
 */
export const FileSizeInput = forwardRef<HTMLInputElement, FileSizeInputProps>(
  function FileSizeInput(
    { label, hint, showBytes = true, className, id: idProp, ...rest },
    ref,
  ) {
    const reactId = useId()
    const id = idProp ?? reactId

    const api = useFileSizeInput({ ...rest, id })
    const {
      inputProps,
      ariaProps,
      containerProps,
      hiddenInputProps,
      ownsErrorUI,
      errorText,
      errorId,
      visible,
      bytes,
      bytesLabel,
    } = api

    useImperativeHandle(
      ref,
      () =>
        inputProps.ref.current ??
        ({ focus: () => inputProps.ref.current?.focus() } as HTMLInputElement),
      [inputProps.ref],
    )

    return (
      <div className={`inputcn-field ${className ?? ""}`.trim()} {...containerProps}>
        {label === undefined ? null : (
          <label className="inputcn-label" htmlFor={id}>
            {label}
          </label>
        )}

        <div
          className="inputcn-group"
          data-invalid={ariaProps["aria-invalid"] ? "true" : undefined}
        >
          <input
            {...inputProps}
            {...ariaProps}
            id={id}
            className="inputcn-bare"
            aria-label={rest["aria-label"]}
            aria-labelledby={rest["aria-labelledby"]}
          />
          {showBytes && bytes > 0 ? (
            <span
              className="inputcn-affix inputcn-affix-right inputcn-mono"
              aria-hidden="true"
            >
              {bytesLabel} B
            </span>
          ) : null}
        </div>

        {ownsErrorUI && errorText ? (
          <p
            id={errorId}
            className={visible?.warning ? "inputcn-warning" : "inputcn-error"}
            // Stable rule name so a test can assert WHICH rule failed rather
            // than matching copy, which breaks on a rewrite or a locale change.
            data-rule={visible?.rule}
            role="alert"
          >
            {errorText}
          </p>
        ) : hint !== undefined ? (
          <p className="inputcn-hint">{hint}</p>
        ) : null}

        {hiddenInputProps ? <input {...hiddenInputProps} /> : null}
      </div>
    )
  },
)

"use client"

import { useCallback, useMemo, useRef, useState, type ClipboardEvent } from "react"

import { clipboardText } from "@inputcn/core/paste"
import type { BaseFieldProps, Rule } from "@inputcn/core/types"
import { useField, type UseFieldResult } from "@inputcn/core/use-field"
import {
  custom,
  max as maxRule,
  min as minRule,
  required as requiredRule,
  rules,
} from "@inputcn/core/validity"

import {
  formatFileSize,
  groupBytes,
  parseFileSize,
  parsePastedFileSize,
  type ParseOptions,
} from "./filesize"

/** Bounds accept human text so the prop reads like the rule: max="100MB". */
export type SizeBound = number | string

export interface FileSizeConstraints {
  min?: SizeBound
  max?: SizeBound
}

export interface UseFileSizeInputOptions
  extends BaseFieldProps<number>,
    FileSizeConstraints {
  /** Use KiB/MiB/GiB and read ambiguous units as powers of 1024. Default false. */
  binary?: boolean
  /** Unit assumed when the user types a bare number. Default "MB". */
  bareUnit?: string
  /** Decimals when formatting. Default 2. */
  precision?: number
  /** Grouping locale for the raw byte readout. Default "en-US". */
  locale?: string
}

export interface UseFileSizeInputResult extends UseFieldResult<number> {
  /** Normalised human text for the current value. */
  display: string
  /** The byte count, for a secondary readout. */
  bytes: number
  /** The byte count, grouped deterministically for display. */
  bytesLabel: string
  inputProps: {
    ref: React.RefObject<HTMLInputElement | null>
    value: string
    onChange: (e: React.ChangeEvent<HTMLInputElement>) => void
    onBlur: () => void
    onPaste: (e: ClipboardEvent<HTMLInputElement>) => void
    autoComplete: "off"
    disabled: boolean | undefined
    readOnly: boolean | undefined
    placeholder: string | undefined
  }
}

function toBytes(bound: SizeBound | undefined, opts: ParseOptions): number | undefined {
  if (bound === undefined) return undefined
  if (typeof bound === "number") return bound
  return parseFileSize(bound, opts) ?? undefined
}

export function useFileSizeInput(
  options: UseFileSizeInputOptions,
): UseFileSizeInputResult {
  const {
    binary = false,
    bareUnit = "MB",
    precision = 2,
    locale = "en-US",
    min,
    max,
    required,
    validate,
    disabled,
    readOnly,
    placeholder,
    ...base
  } = options

  const parseOpts = useMemo<ParseOptions>(() => ({ binary, bareUnit }), [binary, bareUnit])
  const fmt = useCallback(
    (b: number) => formatFileSize(b, { binary, precision }),
    [binary, precision],
  )

  const minB = useMemo(() => toBytes(min, parseOpts), [min, parseOpts])
  const maxB = useMemo(() => toBytes(max, parseOpts), [max, parseOpts])

  const ruleList = useMemo<ReadonlyArray<Rule<number>>>(
    () =>
      rules<number>(
        requiredRule<number>(required),
        minRule(minB, fmt),
        maxRule(maxB, fmt),
        custom<number>(validate),
      ),
    [required, minB, maxB, fmt, validate],
  )

  const field = useField<number>({
    component: "FileSizeInput",
    emptyValue: 0,
    rules: ruleList,
    ...base,
    required,
    disabled,
    readOnly,
    serialize: (v) => String(v),
  })

  const { value, setValue } = field
  const ref = useRef<HTMLInputElement | null>(null)

  // Draft keeps what was typed; without it "25 M" would reformat mid-word.
  const [draft, setDraft] = useState<string | null>(null)
  const normalised = value === 0 ? "" : fmt(value)
  const display = draft ?? normalised

  const onChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      if (disabled || readOnly) return
      const text = e.currentTarget.value
      setDraft(text)
      const parsed = parseFileSize(text, parseOpts)
      // null means unparseable — keep the last good value rather than zeroing
      // it, so a half-typed unit does not wipe the field.
      if (parsed !== null) setValue(parsed)
      else if (text.trim() === "") setValue(0)
    },
    [disabled, readOnly, setValue, parseOpts],
  )

  const onBlur = useCallback(() => setDraft(null), [])

  const onPaste = useCallback(
    (e: ClipboardEvent<HTMLInputElement>) => {
      if (disabled || readOnly) return
      const text = clipboardText(e)
      if (!text) return
      e.preventDefault()
      const parsed = parsePastedFileSize(text, parseOpts)
      if (parsed === null) return
      setDraft(null)
      setValue(parsed)
    },
    [disabled, readOnly, setValue, parseOpts],
  )

  const inputProps = useMemo(
    () => ({
      ref,
      value: display,
      onChange,
      onBlur,
      onPaste,
      autoComplete: "off" as const,
      disabled,
      readOnly,
      placeholder: placeholder ?? (binary ? "25 MiB" : "25 MB"),
    }),
    [display, onChange, onBlur, onPaste, disabled, readOnly, placeholder, binary],
  )

  return {
    ...field,
    display: normalised,
    bytes: value,
    bytesLabel: groupBytes(value, locale),
    inputProps,
  }
}

/**
 * File size parsing and formatting. Framework-free.
 *
 * Canonical value is BYTES as an integer.
 *
 * The distinction that matters and that everyone gets wrong: `MB` is 1000²,
 * `MiB` is 1024². They differ by 4.9% at mega and 7.4% at giga, which is the
 * gap between "100 MB upload limit" and a user's file being rejected. This
 * module keeps them separate and never silently converts one to the other.
 */

import { scrub } from "@inputcn/core/paste"

export type Unit = "B" | "KB" | "MB" | "GB" | "TB" | "PB"
export type BinaryUnit = "B" | "KiB" | "MiB" | "GiB" | "TiB" | "PiB"

export const DECIMAL_UNITS: readonly Unit[] = ["B", "KB", "MB", "GB", "TB", "PB"]
export const BINARY_UNITS: readonly BinaryUnit[] = ["B", "KiB", "MiB", "GiB", "TiB", "PiB"]

/** Multiplier per unit. Lowercase keys so lookup is case-insensitive. */
const FACTORS: ReadonlyMap<string, number> = new Map([
  ["b", 1], ["byte", 1], ["bytes", 1],
  ["k", 1e3], ["kb", 1e3], ["kilobyte", 1e3], ["kilobytes", 1e3],
  ["m", 1e6], ["mb", 1e6], ["megabyte", 1e6], ["megabytes", 1e6],
  ["g", 1e9], ["gb", 1e9], ["gigabyte", 1e9], ["gigabytes", 1e9],
  ["t", 1e12], ["tb", 1e12], ["terabyte", 1e12], ["terabytes", 1e12],
  ["p", 1e15], ["pb", 1e15],
  ["kib", 1024], ["mib", 1024 ** 2], ["gib", 1024 ** 3],
  ["tib", 1024 ** 4], ["pib", 1024 ** 5],
])

// Hoisted — runs on every keystroke.
const SIZE_RE = /^\s*([\d.,]+)\s*([a-z]*)\s*$/i

export interface ParseOptions {
  /** Unit assumed when none is written. Default "B". */
  bareUnit?: string
  /** Read ambiguous units (KB, MB…) as powers of 1024. Default false. */
  binary?: boolean
}

/**
 * Parse human size text into bytes.
 * Returns null — not 0 — when unparseable, so "invalid" and "zero bytes" stay
 * distinguishable.
 */
export function parseFileSize(
  input: string,
  { bareUnit = "B", binary = false }: ParseOptions = {},
): number | null {
  const text = scrub(input)
  if (!text) return null

  const m = SIZE_RE.exec(text)
  if (!m) return null

  const n = Number.parseFloat(m[1]!.replace(/,/g, ""))
  if (!Number.isFinite(n) || n < 0) return null

  const unit = (m[2] || bareUnit).toLowerCase()
  let factor = FACTORS.get(unit)
  if (factor === undefined) return null

  // In binary mode the ambiguous SI-looking units mean powers of 1024. The
  // explicitly binary ones (KiB…) are never reinterpreted.
  if (binary && !unit.includes("i") && factor > 1) {
    const power = Math.round(Math.log10(factor) / 3)
    factor = 1024 ** power
  }

  return Math.round(n * factor)
}

export interface FormatOptions {
  /** Use KiB/MiB/GiB. Default false. */
  binary?: boolean
  /** Significant decimals. Default 2, trailing zeros trimmed. */
  precision?: number
  /** Force a specific unit instead of picking the most readable one. */
  unit?: string
}

/** Bytes → the most readable human string. `26214400` → `"26.21 MB"`. */
export function formatFileSize(
  bytes: number,
  { binary = false, precision = 2, unit }: FormatOptions = {},
): string {
  if (!Number.isFinite(bytes) || bytes < 0) return ""
  if (bytes === 0) return "0 B"

  const base = binary ? 1024 : 1000
  const units = binary ? BINARY_UNITS : DECIMAL_UNITS

  let index: number
  if (unit) {
    const found = units.findIndex((u) => u.toLowerCase() === unit.toLowerCase())
    index = found === -1 ? 0 : found
  } else {
    index = Math.min(Math.floor(Math.log(bytes) / Math.log(base)), units.length - 1)
  }

  const value = bytes / base ** index
  // Bytes are never fractional; larger units keep the requested precision.
  const decimals = index === 0 ? 0 : precision
  const trimmed = Number.parseFloat(value.toFixed(decimals))
  return `${trimmed} ${units[index]}`
}

/** Cached grouping formatter for the raw byte readout. */
const groupers = new Map<string, Intl.NumberFormat>()

/**
 * Group a byte count for display.
 *
 * Takes an explicit locale rather than calling `toLocaleString()`, which
 * follows the host machine and would render 25000000 as "2,50,00,000" on an
 * en-IN system. A technical readout must not depend on where it is rendered.
 */
export function groupBytes(bytes: number, locale = "en-US"): string {
  let fmt = groupers.get(locale)
  if (!fmt) {
    fmt = new Intl.NumberFormat(locale, { useGrouping: true, maximumFractionDigits: 0 })
    groupers.set(locale, fmt)
  }
  return fmt.format(bytes)
}

/** Round-trip helper: is this text a size we understand? */
export function isValidFileSize(input: string, options?: ParseOptions): boolean {
  return parseFileSize(input, options) !== null
}

/** Smart paste — the same parser, since it is already tolerant. */
export function parsePastedFileSize(
  input: string,
  options?: ParseOptions,
): number | null {
  const text = scrub(input)
  if (!text) return null

  const direct = parseFileSize(text, options)
  if (direct !== null) return direct

  // Pull a size token out of a longer sentence: "Max upload: 25 MB".
  const token = /([\d.,]+)\s*([kmgtp]i?b|bytes?|[kmgtp])\b/i.exec(text)
  return token ? parseFileSize(token[0], options) : null
}
